-- Bookings. Double booking is ruled out by the database itself, not by
-- application code: "check the slot is free, then insert" races (two
-- requests both see it free, both insert) at any isolation level below
-- SERIALIZABLE. The constraints below are checked atomically by PostgreSQL,
-- so of two concurrent inserts for the same person and time, exactly one wins.

-- Lets one GiST index compare plain text with `=` next to a time range.
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE bookings (
  id            uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Generated by the browser once per booking form. A double click or a
  -- network retry sends the same id, and the second insert does nothing.
  request_id    uuid        NOT NULL,
  -- Short code shown at the front desk: "TS-7K2Q9".
  code          text        NOT NULL,
  business_slug text        NOT NULL,
  staff_id      text        NOT NULL,
  service_name  text        NOT NULL,
  duration_min  integer     NOT NULL,
  price         integer     NOT NULL,
  starts_at     timestamptz NOT NULL,
  ends_at       timestamptz NOT NULL,
  customer_name text        NOT NULL,
  phone         text        NOT NULL,
  note          text        NOT NULL DEFAULT '',
  status        text        NOT NULL DEFAULT 'confirmed',
  -- When the customer agreed to their data being used (Law on Personal Data Protection).
  consented_at  timestamptz NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  cancelled_at  timestamptz,

  CONSTRAINT bookings_request_id_key UNIQUE (request_id),
  CONSTRAINT bookings_code_key UNIQUE (code),
  CONSTRAINT bookings_duration_positive CHECK (duration_min > 0),
  CONSTRAINT bookings_price_not_negative CHECK (price >= 0),
  CONSTRAINT bookings_ends_after_start CHECK (ends_at > starts_at),
  CONSTRAINT bookings_phone_format CHECK (phone ~ '^[6-9][0-9]{7}$'),
  CONSTRAINT bookings_status_valid CHECK (status IN ('confirmed', 'cancelled')),
  CONSTRAINT bookings_cancelled_at_matches_status
    CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL)),

  -- No two confirmed bookings for the same person may overlap in time.
  -- A plain UNIQUE (staff_id, starts_at) is not enough: it only catches
  -- identical start times, so a 45-minute booking at 10:00 and another at
  -- 10:30 would both get in. `&&` catches any overlap. The range is
  -- half-open, '[)', so 10:00–10:45 and 10:45–11:30 can sit back to back.
  -- Cancelled bookings are left out, which frees their time at once.
  CONSTRAINT bookings_no_overlap EXCLUDE USING gist (
    business_slug WITH =,
    staff_id WITH =,
    tstzrange(starts_at, ends_at, '[)') WITH &&
  ) WHERE (status = 'confirmed')
);

-- "My bookings" by phone number, once accounts arrive.
CREATE INDEX bookings_phone_idx ON bookings (phone, starts_at DESC);
